def ticket_for_line(store, line: StatementLine) -> Optional[Ticket]:
    if line.account_ref is None:
        return None
    target = "".join(c.lower() for c in line.account_ref if c.isalnum())
    for ticket in store.tickets.values():
        ticket_id = "".join(c.lower() for c in ticket.id if c.isalnum())
        if target == ticket_id:
            return ticket

    if target.startswith("ticket"):
        remaining = target[6:]
        for ticket in store.tickets.values():
            ticket_id = "".join(c.lower() for c in ticket.id if c.isalnum())
            if remaining == ticket_id:
                return ticket
    elif target.startswith("tkt"):
        remaining = target[3:]
        for ticket in store.tickets.values():
            ticket_id = "".join(c.lower() for c in ticket.id if c.isalnum())
            if remaining == ticket_id:
                return ticket
    return None

